package com.glassbox.uml; import com.glassbox.uml.event.*; import com.glassbox.chess.domain.Position; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import java.util.concurrent.atomic.AtomicInteger; public class EventBusTest{@Test void observerFailureDoesNotBreakPublisher(){EventBus b=EventBus.getInstance();b.clearAllSubscribers();AtomicInteger n=new AtomicInteger();b.subscribe(DomainEvents.GameStarted.class,e->{throw new RuntimeException("test");});b.subscribe(DomainEvents.GameStarted.class,e->n.incrementAndGet());assertDoesNotThrow(()->b.publish(new DomainEvents.GameStarted()));assertEquals(1,n.get());b.clearAllSubscribers();}}
